package dev.gbppimentel.zzz;
import android.database.*;import android.database.sqlite.*;import org.json.*;
public final class DeviceStatsProbe {public static void main(String[] args)throws Exception{try(SQLiteDatabase db=SQLiteDatabase.openDatabase("/data/user/0/rip.moth.cocoonshell/databases/cocoon_db",null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS)){JSONArray columns=new JSONArray();try(Cursor c=db.rawQuery("PRAGMA table_info(games)",null)){while(c.moveToNext())columns.put(c.getString(1));}System.out.println(new JSONObject().put("gameColumns",columns));try(Cursor c=db.rawQuery("SELECT id,displayName,playTimeMinutes,uri,trackPlaytime FROM games WHERE displayName LIKE '%Zenless%' LIMIT 3",null)){JSONArray games=new JSONArray();while(c.moveToNext())games.put(new JSONObject().put("id",c.getLong(0)).put("name",c.getString(1)).put("minutes",c.getLong(2)).put("uri",c.getString(3)).put("tracking",c.getInt(4)));System.out.println(games);}}}}
